    /// The order is the ABI. The last two flags switch on hover and pointer actions.
    ///
    /// WIT `ilium:types/ui.node-flags`, reference-wit.md section 4.10.
    #[derive(
        Debug, Clone, Copy, PartialEq, Eq, Hash, Default, serde::Serialize, serde::Deserialize,
    )]
    #[serde(transparent)]
    #[repr(transparent)]
    pub struct NodeFlags(pub u32);

    impl NodeFlags {
        /// Flag `focusable` (bit 0).
        pub const FOCUSABLE: NodeFlags = NodeFlags(1 << 0);
        /// Flag `draggable` (bit 1).
        pub const DRAGGABLE: NodeFlags = NodeFlags(1 << 1);
        /// Flag `drop-target` (bit 2).
        pub const DROP_TARGET: NodeFlags = NodeFlags(1 << 2);
        /// Flag `hidden` (bit 3).
        pub const HIDDEN: NodeFlags = NodeFlags(1 << 3);
        /// Flag `hover-events` (bit 4).
        pub const HOVER_EVENTS: NodeFlags = NodeFlags(1 << 4);
        /// Flag `pointer-events` (bit 5).
        pub const POINTER_EVENTS: NodeFlags = NodeFlags(1 << 5);
        /// The WIT flag names in declaration order; flag `n` is bit `n`.
        pub const CASE_NAMES: &'static [&'static str] = &[
            "focusable",
            "draggable",
            "drop-target",
            "hidden",
            "hover-events",
            "pointer-events",
        ];
        /// Every flag of `node-flags` set.
        pub const ALL: NodeFlags = NodeFlags(0x3f);

        /// No flag set.
        pub const fn empty() -> NodeFlags {
            NodeFlags(0)
        }

        /// The raw bits.
        pub const fn bits(self) -> u32 {
            self.0
        }

        /// True when every flag of `other` is set in `self`.
        pub const fn contains(self, other: NodeFlags) -> bool {
            self.0 & other.0 == other.0
        }

        /// True when no flag is set.
        pub const fn is_empty(self) -> bool {
            self.0 == 0
        }

        /// Sets every flag of `other`.
        pub fn insert(&mut self, other: NodeFlags) {
            self.0 |= other.0;
        }

        /// Clears every flag of `other`.
        pub fn remove(&mut self, other: NodeFlags) {
            self.0 &= !other.0;
        }
    }

    impl std::ops::BitOr for NodeFlags {
        type Output = NodeFlags;

        fn bitor(self, other: NodeFlags) -> NodeFlags {
            NodeFlags(self.0 | other.0)
        }
    }

    impl std::ops::BitAnd for NodeFlags {
        type Output = NodeFlags;

        fn bitand(self, other: NodeFlags) -> NodeFlags {
            NodeFlags(self.0 & other.0)
        }
    }

    impl std::ops::BitOrAssign for NodeFlags {
        fn bitor_assign(&mut self, other: NodeFlags) {
            self.0 |= other.0;
        }
    }

