    #[serde(transparent)]
    #[repr(transparent)]
    pub struct PointerModifiers(pub u32);

    impl PointerModifiers {
        /// Flag `shift` (bit 0).
        pub const SHIFT: PointerModifiers = PointerModifiers(1 << 0);
        /// Flag `control` (bit 1).
        pub const CONTROL: PointerModifiers = PointerModifiers(1 << 1);
        /// Flag `alt` (bit 2).
        pub const ALT: PointerModifiers = PointerModifiers(1 << 2);
        /// The WIT flag names in declaration order; flag `n` is bit `n`.
        pub const CASE_NAMES: &'static [&'static str] = &["shift", "control", "alt"];
        /// Every flag of `pointer-modifiers` set.
        pub const ALL: PointerModifiers = PointerModifiers(0x7);

        /// No flag set.
        pub const fn empty() -> PointerModifiers {
            PointerModifiers(0)
        }

        /// The raw bits.
        pub const fn bits(self) -> u32 {
            self.0
        }

        /// True when every flag of `other` is set in `self`.
        pub const fn contains(self, other: PointerModifiers) -> bool {
            self.0 & other.0 == other.0
        }

        /// True when no flag is set.
        pub const fn is_empty(self) -> bool {
            self.0 == 0
        }

        /// Sets every flag of `other`.
        pub fn insert(&mut self, other: PointerModifiers) {
            self.0 |= other.0;
        }

        /// Clears every flag of `other`.
        pub fn remove(&mut self, other: PointerModifiers) {
            self.0 &= !other.0;
        }
    }

    impl std::ops::BitOr for PointerModifiers {
        type Output = PointerModifiers;

        fn bitor(self, other: PointerModifiers) -> PointerModifiers {
            PointerModifiers(self.0 | other.0)
        }
    }

    impl std::ops::BitAnd for PointerModifiers {
        type Output = PointerModifiers;

        fn bitand(self, other: PointerModifiers) -> PointerModifiers {
            PointerModifiers(self.0 & other.0)
        }
    }

    impl std::ops::BitOrAssign for PointerModifiers {
        fn bitor_assign(&mut self, other: PointerModifiers) {
            self.0 |= other.0;
        }
    }

